/*
 * A137037  Numbers k such that k and k^2 use only the digits 1, 3, 6 and 7.
 * https://oeis.org/A137037
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn, more
 * Formula:   a(n) = the n-th natural number whose decimal digits are only
 *            1,3,6,7 and whose square also contains only 1,3,6,7
 * Range:     u8 n <= 2, u16 n <= 3, u32 n <= 4, u64 n <= 9, u128 n <= 9,
 *            big any n
 * Helpers:   is_allowed_digits
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by brute‑force search; it is
   memoised so that a(n) can be requested in any order. */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_allowed_digits.h"

static seq_t *term_cache = NULL;          /* 1‑based storage of generated terms   */
static size_t cache_size = 0;             /* number of terms stored               */
static size_t cache_cap  = 0;             /* current allocated capacity           */
static size_t current_len = 0;            /* length of numbers last generated     */

static const int allowed_digits_list[4] = {1, 3, 6, 7};

/* Ensure the cache can hold 'need' terms */
static void ensure_cache_capacity(size_t need)
{
    if (need <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap : 16;
    while (new_cap < need)
        new_cap <<= 1;
    seq_t *new_ptr = (seq_t *)realloc(term_cache, new_cap * sizeof(seq_t));
    term_cache = new_ptr;
    cache_cap  = new_cap;
}

/* Recursively generate all numbers of 'len' digits using
   digits {1,3,6,7}; each candidate is passed to the callback. */
static void generate_len_rec(int pos, int len, seq_t acc,
                             void (*cb)(seq_t))
{
    if (pos == len) {
        cb(acc);
        return;
    }
    for (int idx = 0; idx < 4; ++idx) {
        generate_len_rec(pos + 1, len,
                         acc * (seq_t)10 + (seq_t)allowed_digits_list[idx], cb);
    }
}

/* Callback used to collect valid terms during generation */
static void collect_candidate(seq_t val)
{
    seq_t sq = val * val;
    if (is_allowed_digits(sq)) {
        ensure_cache_capacity(cache_size + 1);
        term_cache[cache_size++] = val;
    }
}

/* Ensure that at least 'n' terms are generated and stored in the cache. */
static void generate_terms(idx_t n)
{
    while (cache_size < (size_t)n) {
        /* generate all numbers of length current_len+1 */
        current_len++;
        generate_len_rec(0, (int)current_len, (seq_t)0, collect_candidate);
        /* If no new terms are found the loop will terminate because
           cache_size will never increase. */
    }
}

/* Public function required by the interface */
seq_t a(idx_t n)
{
    /* The sequence is indexed from 1; a(1) is the first term. */
    if (n == 0)
        return (seq_t)0;          /* undefined, but safe fallback */

    generate_terms(n);
    /* Return the nth term (1‑based index). */
    return term_cache[n - 1];
}
